"""Adds config flow for Google Home."""

import ipaddress
import logging
from typing import Self, override

from glocaltokens.utils.token import is_aas_et
import probatio
from requests.exceptions import RequestException

from homeassistant.config_entries import ConfigFlow, ConfigFlowResult, OptionsFlow
from homeassistant.core import callback
from homeassistant.helpers.aiohttp_client import async_create_clientsession
from homeassistant.helpers.selector import SelectSelector, SelectSelectorConfig

from .api import GlocaltokensApiClient
from .const import (
    BROWSER_TITLE,
    CONF_ANDROID_ID,
    CONF_KNOWN_HOSTS,
    CONF_MASTER_TOKEN,
    CONF_OAUTH_TOKEN,
    CONF_PASSWORD,
    CONF_UPDATE_INTERVAL,
    CONF_USERNAME,
    DOMAIN,
    MASTER_TOKEN_TITLE,
    UPDATE_INTERVAL,
)
from .exceptions import InvalidMasterToken
from .types import GoogleHomeConfigEntry, OptionsFlowDict

_LOGGER: logging.Logger = logging.getLogger(__package__)

STEP_BROWSER = "browser"
STEP_MASTER_TOKEN = "master_token"

OAUTH_TOKEN_PREFIX = "oauth2_4/"

DESCRIPTION_PLACEHOLDERS = {
    "docs_url": "https://ha-google-home.pages.dev/installation/",
    "browser_docs_url": "https://ha-google-home.pages.dev/installation/#browser-sign-in",
    "embedded_setup_url": "https://accounts.google.com/EmbeddedSetup",
}


class GoogleHomeFlowHandler(ConfigFlow, domain=DOMAIN):
    """Config flow for GoogleHome."""

    VERSION = 1
    # 2: app passwords that older versions saved are cleared
    MINOR_VERSION = 2

    def __init__(self) -> None:
        """Initialize."""
        self.username: str | None = None

    @override
    def is_matching(self, other_flow: Self) -> bool:
        """Return True if other_flow is matching this flow."""
        return other_flow.username == self.username

    @override
    async def async_step_user(
        self,
        user_input: dict[str, str] | None = None,
    ) -> ConfigFlowResult:
        """Ask how to sign in."""
        return self.async_show_menu(
            step_id="user",
            menu_options=[STEP_BROWSER, STEP_MASTER_TOKEN],
            description_placeholders=DESCRIPTION_PLACEHOLDERS,
        )

    async def async_step_browser(
        self, user_input: dict[str, str] | None = None
    ) -> ConfigFlowResult:
        """Sign in with the oauth_token cookie from a browser sign-in."""
        errors: dict[str, str] = {}
        if user_input is not None:
            oauth_token = user_input[CONF_OAUTH_TOKEN].strip()
            if not oauth_token.startswith(OAUTH_TOKEN_PREFIX):
                errors[CONF_OAUTH_TOKEN] = "oauth-token-format"
            else:
                client = GlocaltokensApiClient(
                    hass=self.hass,
                    session=async_create_clientsession(self.hass),
                    oauth_token=oauth_token,
                )
                # Getting the master token exchanges the cookie for it
                if await self._sign_in(client):
                    username = await client.async_get_email() or ""
                    self.username = username
                    return await self._create_entry(
                        client, username, username or BROWSER_TITLE
                    )
                errors["base"] = "oauth-token-invalid"
        return self._show_form(
            STEP_BROWSER,
            {probatio.Required(CONF_OAUTH_TOKEN): str},
            errors,
        )

    async def async_step_master_token(
        self, user_input: dict[str, str] | None = None
    ) -> ConfigFlowResult:
        """Sign in with an existing master token."""
        errors: dict[str, str] = {}
        if user_input is not None:
            master_token = user_input[CONF_MASTER_TOKEN].strip()
            if not is_aas_et(master_token):
                errors[CONF_MASTER_TOKEN] = "master-token-format"
            else:
                client = GlocaltokensApiClient(
                    hass=self.hass,
                    session=async_create_clientsession(self.hass),
                    username="",
                    password="",
                    master_token=master_token,
                )
                if await self._sign_in(client):
                    username = await client.async_get_email() or ""
                    self.username = username
                    return await self._create_entry(
                        client, username, username or MASTER_TOKEN_TITLE
                    )
                errors["base"] = "master-token-invalid"
        return self._show_form(
            STEP_MASTER_TOKEN,
            {probatio.Required(CONF_MASTER_TOKEN): str},
            errors,
        )

    async def _create_entry(
        self,
        client: GlocaltokensApiClient,
        username: str,
        title: str,
    ) -> ConfigFlowResult:
        """Save the master token that every sign-in method ends with."""
        return self.async_create_entry(
            title=title,
            data={
                CONF_MASTER_TOKEN: await client.async_get_master_token(),
                CONF_USERNAME: username,
                # Older versions saved an app password here
                CONF_PASSWORD: "",
                CONF_ANDROID_ID: await client.get_android_id(),
            },
        )

    def _show_form(
        self,
        step_id: str,
        schema: dict[probatio.Marker, type],
        errors: dict[str, str],
    ) -> ConfigFlowResult:
        """Show the form of one sign-in method."""
        return self.async_show_form(
            step_id=step_id,
            data_schema=probatio.Schema(schema),
            errors=errors,
            description_placeholders=DESCRIPTION_PLACEHOLDERS,
        )

    @staticmethod
    @callback
    @override
    def async_get_options_flow(
        config_entry: GoogleHomeConfigEntry,
    ) -> GoogleHomeOptionsFlowHandler:
        """Handle options flow."""
        return GoogleHomeOptionsFlowHandler()

    @staticmethod
    async def _sign_in(client: GlocaltokensApiClient) -> bool:
        """Return whether Google gives a master token and an access token."""
        try:
            await client.async_get_master_token()
            await client.async_get_access_token()
        except InvalidMasterToken, RequestException:
            _LOGGER.exception("Failed to sign in")
            return False
        return True


class GoogleHomeOptionsFlowHandler(OptionsFlow):
    """Config flow options handler for GoogleHome."""

    async def async_step_init(
        self, user_input: OptionsFlowDict | None = None
    ) -> ConfigFlowResult:
        """Manage the options."""
        errors: dict[str, str] = {}
        options: dict[str, object] = dict(self.config_entry.options)
        if user_input is not None:
            # Keep the order, which decides between hosts that report the same device
            known_hosts = list(
                dict.fromkeys(
                    host.strip()
                    for host in user_input.get(CONF_KNOWN_HOSTS, [])
                    if host.strip()
                )
            )
            if all(_is_ip_address(host) for host in known_hosts):
                return self.async_create_entry(
                    data={**user_input, CONF_KNOWN_HOSTS: known_hosts}
                )
            errors[CONF_KNOWN_HOSTS] = "known-host-not-ip"
            options = {**options, **user_input}

        return self.async_show_form(
            step_id="init",
            data_schema=probatio.Schema(
                {
                    probatio.Optional(
                        CONF_UPDATE_INTERVAL,
                        default=options.get(CONF_UPDATE_INTERVAL, UPDATE_INTERVAL),
                    ): int,
                    probatio.Optional(
                        CONF_KNOWN_HOSTS,
                        default=options.get(CONF_KNOWN_HOSTS, []),
                    ): SelectSelector(
                        SelectSelectorConfig(
                            custom_value=True, options=[], multiple=True
                        )
                    ),
                }
            ),
            errors=errors,
        )


def _is_ip_address(host: str) -> bool:
    """Return whether a known host is an IP address, which requests need."""
    try:
        ipaddress.ip_address(host)
    except ValueError:
        return False
    return True

"""Sensor platform for Google Home."""

import asyncio
from enum import IntFlag
import logging
from typing import override

import probatio

from homeassistant.components.sensor import SensorDeviceClass
from homeassistant.const import STATE_UNAVAILABLE, EntityCategory
from homeassistant.core import HomeAssistant, ServiceCall
from homeassistant.helpers import config_validation as cv, entity_platform, service
from homeassistant.helpers.entity_platform import AddEntitiesCallback
from homeassistant.helpers.update_coordinator import DataUpdateCoordinator

from .api import GlocaltokensApiClient
from .const import (
    ALARM_AND_TIMER_ID_LENGTH,
    DATA_CLIENT,
    DATA_COORDINATOR,
    DOMAIN,
    GOOGLE_HOME_ALARM_DEFAULT_VALUE,
    ICON_ALARMS,
    ICON_TIMERS,
    ICON_TOKEN,
    LABEL_ALARMS,
    LABEL_DEVICE,
    LABEL_TIMERS,
    SENSOR,
    SERVICE_ATTR_ALARM_ID,
    SERVICE_ATTR_SKIP_REFRESH,
    SERVICE_ATTR_TIMER_ID,
    SERVICE_DELETE_ALARM,
    SERVICE_DELETE_ALL_ALARMS,
    SERVICE_DELETE_ALL_TIMERS,
    SERVICE_DELETE_TIMER,
    SERVICE_REBOOT,
    SERVICE_REFRESH,
)
from .entity import GoogleHomeBaseEntity, async_add_device_entities
from .models import GoogleHomeAlarmStatus, GoogleHomeDevice, GoogleHomeTimerStatus
from .types import (
    AlarmsAttributes,
    DeviceAttributes,
    GoogleHomeAlarmDict,
    GoogleHomeConfigEntry,
    GoogleHomeTimerDict,
    TimersAttributes,
)

_LOGGER: logging.Logger = logging.getLogger(__package__)


class GoogleHomeSensorFeature(IntFlag):
    """Actions a sensor supports, so a device target runs each on its own sensor."""

    ALARMS = 1
    TIMERS = 2


async def async_setup_entry(
    hass: HomeAssistant,
    entry: GoogleHomeConfigEntry,
    async_add_devices: AddEntitiesCallback,
) -> bool:
    """Set up sensor platform."""
    client: GlocaltokensApiClient = hass.data[DOMAIN][entry.entry_id][DATA_CLIENT]
    coordinator: DataUpdateCoordinator[list[GoogleHomeDevice]] = hass.data[DOMAIN][
        entry.entry_id
    ][DATA_COORDINATOR]
    async_add_device_entities(
        entry,
        coordinator,
        client,
        async_add_devices,
        GoogleHomeDeviceSensor,
        needs_answer=False,
    )
    async_add_device_entities(
        entry,
        coordinator,
        client,
        async_add_devices,
        GoogleHomeAlarmsSensor,
        GoogleHomeTimersSensor,
    )

    platform = entity_platform.async_get_current_platform()

    # Services
    platform.async_register_entity_service(
        SERVICE_DELETE_ALARM,
        {
            probatio.Required(SERVICE_ATTR_ALARM_ID): cv.string,
            probatio.Optional(SERVICE_ATTR_SKIP_REFRESH): cv.boolean,
        },
        GoogleHomeAlarmsSensor.async_delete_alarm,
        [GoogleHomeSensorFeature.ALARMS],
    )

    platform.async_register_entity_service(
        SERVICE_DELETE_TIMER,
        {
            probatio.Required(SERVICE_ATTR_TIMER_ID): cv.string,
            probatio.Optional(SERVICE_ATTR_SKIP_REFRESH): cv.boolean,
        },
        GoogleHomeTimersSensor.async_delete_timer,
        [GoogleHomeSensorFeature.TIMERS],
    )

    platform.async_register_entity_service(
        SERVICE_DELETE_ALL_ALARMS,
        {probatio.Optional(SERVICE_ATTR_SKIP_REFRESH): cv.boolean},
        GoogleHomeAlarmsSensor.async_delete_all_alarms,
        [GoogleHomeSensorFeature.ALARMS],
    )

    platform.async_register_entity_service(
        SERVICE_DELETE_ALL_TIMERS,
        {probatio.Optional(SERVICE_ATTR_SKIP_REFRESH): cv.boolean},
        GoogleHomeTimersSensor.async_delete_all_timers,
        [GoogleHomeSensorFeature.TIMERS],
    )

    service.async_register_batched_platform_entity_service(
        hass,
        DOMAIN,
        SERVICE_REBOOT,
        entity_domain=SENSOR,
        schema={},
        func=async_reboot_devices,
    )

    platform.async_register_entity_service(
        SERVICE_REFRESH,
        {},
        async_refresh_devices,
    )

    return True


async def async_refresh_devices(
    entity: GoogleHomeBaseEntity, _call: ServiceCall
) -> None:
    """Refresh all devices, from whichever Google Home sensor is targeted."""
    await entity.coordinator.async_request_refresh()


async def async_delete(
    entity: GoogleHomeBaseEntity,
    call: ServiceCall,
    device: GoogleHomeDevice,
    ids: list[str],
) -> None:
    """Delete these alarms or timers from the device and show what is left."""
    if ids:
        await entity.client.delete_alarm_or_timer(device=device, items_to_delete=ids)
    else:
        _LOGGER.debug("Nothing to delete for %s", device.name)
    # Other entities show this device's data too
    entity.coordinator.async_update_listeners()
    if ids and not call.data.get(SERVICE_ATTR_SKIP_REFRESH, False):
        await entity.coordinator.async_request_refresh()


async def async_reboot_devices(
    entities: list[GoogleHomeBaseEntity], _call: ServiceCall
) -> None:
    """Reboot the device of each entity, once per device."""
    one_per_device = {entity.device_id: entity for entity in entities}.values()
    results = await asyncio.gather(
        *(entity.async_reboot_device() for entity in one_per_device),
        return_exceptions=True,
    )
    # Like Home Assistant's per-entity calls: finish every reboot, then raise.
    for result in results:
        if isinstance(result, BaseException):
            raise result


class GoogleHomeDeviceSensor(GoogleHomeBaseEntity):
    """Google Home Device sensor."""

    _attr_icon = ICON_TOKEN
    _attr_entity_category = EntityCategory.DIAGNOSTIC

    @property
    @override
    def label(self) -> str:
        """Label to use for name and unique id."""
        return LABEL_DEVICE

    @property
    @override
    def available(self) -> bool:
        """Return whether the device was found on the network."""
        device = self.get_device()
        return (
            super().available and device is not None and device.ip_address is not None
        )

    @property
    @override
    def state(self) -> str | None:
        """Return device IP address if any."""
        device = self.get_device()
        return device.ip_address if device else None

    @property
    @override
    def extra_state_attributes(self) -> DeviceAttributes:
        """Return the state attributes."""
        device = self.get_device()
        attributes: DeviceAttributes = {
            "device_id": None,
            "device_name": self.device_name,
            "auth_token": None,
            "ip_address": None,
            "available": False,
        }
        return self.get_device_attributes(device) if device else attributes

    @staticmethod
    def get_device_attributes(device: GoogleHomeDevice) -> DeviceAttributes:
        """Device representation as dictionary."""
        return {
            "device_id": device.device_id,
            "device_name": device.name,
            "auth_token": device.auth_token,
            "ip_address": device.ip_address,
            "available": device.available,
        }


class GoogleHomeAlarmsSensor(GoogleHomeBaseEntity):
    """Google Home Alarms sensor."""

    _attr_icon = ICON_ALARMS
    _attr_device_class = SensorDeviceClass.TIMESTAMP
    _attr_supported_features = GoogleHomeSensorFeature.ALARMS

    @property
    @override
    def label(self) -> str:
        """Label to use for name and unique id."""
        return LABEL_ALARMS

    @property
    @override
    def state(self) -> str | None:
        """Return next alarm if available."""
        device = self.get_device()
        if not device:
            return None
        next_alarm = device.get_next_alarm()
        return (
            next_alarm.local_time_iso
            if next_alarm
            and next_alarm.status
            not in {GoogleHomeAlarmStatus.INACTIVE, GoogleHomeAlarmStatus.MISSED}
            else STATE_UNAVAILABLE
        )

    @property
    @override
    def extra_state_attributes(self) -> AlarmsAttributes:
        """Return the state attributes."""
        return {
            "next_alarm_status": self._get_next_alarm_status(),
            "alarm_volume": self._get_alarm_volume(),
            "alarms": self._get_alarms_data(),
        }

    def _get_next_alarm_status(self) -> str:
        """Update next alarm status from coordinator."""
        device = self.get_device()
        next_alarm = device.get_next_alarm() if device else None
        return (
            next_alarm.status.name.lower()
            if next_alarm
            else GoogleHomeAlarmStatus.NONE.name.lower()
        )

    def _get_alarm_volume(self) -> float:
        """Update alarm volume status from coordinator."""
        device = self.get_device()
        alarm_volume = device.get_alarm_volume() if device else None
        return alarm_volume or GOOGLE_HOME_ALARM_DEFAULT_VALUE

    def _get_alarms_data(self) -> list[GoogleHomeAlarmDict]:
        """Update alarms data extracting it from coordinator."""
        device = self.get_device()
        return (
            [alarm.as_dict() for alarm in device.get_sorted_alarms()] if device else []
        )

    @staticmethod
    def is_valid_alarm_id(alarm_id: str) -> bool:
        """Check if the alarm id provided is valid."""
        return (
            alarm_id.startswith("alarm/") and len(alarm_id) == ALARM_AND_TIMER_ID_LENGTH
        )

    async def async_delete_alarm(self, call: ServiceCall) -> None:
        """Service call to delete alarm on device."""
        device = self.get_device()

        if device is None:
            _LOGGER.error("Device %s is not found.", self.device_name)
            return

        alarm_id: str = call.data[SERVICE_ATTR_ALARM_ID]
        if not self.is_valid_alarm_id(alarm_id):
            _LOGGER.error(
                "Incorrect ID format! Please provide a valid alarm ID. "
                "See services tab for more info."
            )
            return

        await async_delete(self, call, device, [alarm_id])

    async def async_delete_all_alarms(self, call: ServiceCall) -> None:
        """Service call to delete all alarms on device."""
        device = self.get_device()

        if device is None:
            _LOGGER.error("Device %s is not found.", self.device_name)
            return

        await self.client.update_alarms_and_timers(device)
        alarm_ids = [alarm.alarm_id for alarm in device.get_sorted_alarms()]
        await async_delete(self, call, device, alarm_ids)


class GoogleHomeTimersSensor(GoogleHomeBaseEntity):
    """Google Home Timers sensor."""

    _attr_icon = ICON_TIMERS
    _attr_device_class = SensorDeviceClass.TIMESTAMP
    _attr_supported_features = GoogleHomeSensorFeature.TIMERS

    @property
    @override
    def label(self) -> str:
        """Label to use for name and unique id."""
        return LABEL_TIMERS

    @property
    @override
    def state(self) -> str | None:
        """Return next timer if available."""
        device = self.get_device()
        if not device:
            return None
        timer = device.get_next_timer()
        return (
            timer.local_time_iso
            if timer and timer.local_time_iso
            else STATE_UNAVAILABLE
        )

    @property
    @override
    def extra_state_attributes(self) -> TimersAttributes:
        """Return the state attributes."""
        return {
            "next_timer_status": self._get_next_timer_status(),
            "timers": self._get_timers_data(),
        }

    def _get_next_timer_status(self) -> str:
        """Update next timer status from coordinator."""
        device = self.get_device()
        next_timer = device.get_next_timer() if device else None
        return (
            next_timer.status.name.lower()
            if next_timer
            else GoogleHomeTimerStatus.NONE.name.lower()
        )

    def _get_timers_data(self) -> list[GoogleHomeTimerDict]:
        """Update timers data extracting it from coordinator."""
        device = self.get_device()
        return (
            [timer.as_dict() for timer in device.get_sorted_timers()] if device else []
        )

    @staticmethod
    def is_valid_timer_id(timer_id: str) -> bool:
        """Check if the timer id provided is valid."""
        return (
            timer_id.startswith("timer/") and len(timer_id) == ALARM_AND_TIMER_ID_LENGTH
        )

    async def async_delete_timer(self, call: ServiceCall) -> None:
        """Service call to delete timer on device."""
        device = self.get_device()

        if device is None:
            _LOGGER.error("Device %s is not found.", self.device_name)
            return

        timer_id: str = call.data[SERVICE_ATTR_TIMER_ID]
        if not self.is_valid_timer_id(timer_id):
            _LOGGER.error(
                "Incorrect ID format! Please provide a valid timer ID. "
                "See services tab for more info."
            )
            return

        await async_delete(self, call, device, [timer_id])

    async def async_delete_all_timers(self, call: ServiceCall) -> None:
        """Service call to delete all timers on device."""
        device = self.get_device()

        if device is None:
            _LOGGER.error("Device %s is not found.", self.device_name)
            return

        await self.client.update_alarms_and_timers(device)
        timer_ids = [timer.timer_id for timer in device.get_sorted_timers()]
        await async_delete(self, call, device, timer_ids)

